const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const westernBasin = ee.Geometry.Polygon([
    [[-83.5, 41.6], [-82.0, 41.6], [-82.0, 42.2], [-83.5, 42.2]]
  ]);
  const easternBasin = ee.Geometry.Polygon([
    [[-82.0, 41.6], [-78.8, 41.6], [-78.8, 42.6], [-82.0, 42.6]]
  ]);
  const date = '2017-09-24';

  // 2. Data Acquisition - Sentinel-2 for chlorophyll detection
  const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(ee.Geometry.Point([-81.5, 41.8]));

  const size = s2.size().getInfo();
  if (size === 0) {
    console.log(`Images on ${date}: 0`);
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Use Floating Algal Index (FAI) as phytoplankton proxy
  const image = s2.first();
  const fai = image.expression(
    'B8 - (B4 + (B11 - B4) * (833 - 665) / (1610 - 665))',
    {
      B8: image.select('B8'),  // NIR
      B4: image.select('B4'),  // Red
      B11: image.select('B11') // SWIR
    }
  ).rename('FAI');

  // Cloud masking
  const qa = image.select('QA60');
  const cloudMask = qa.bitwiseAnd(1 << 10).eq(0)  // Cloud bit
    .and(qa.bitwiseAnd(1 << 11).eq(0)); // Cirrus bit
  const maskedFAI = fai.updateMask(cloudMask);

  // 4. Calculate statistics for each basin
  const statsWest = maskedFAI.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: westernBasin,
    scale: 1000,
    maxPixels: 1e9
  });

  const statsEast = maskedFAI.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: easternBasin,
    scale: 1000,
    maxPixels: 1e9
  });

  const countWest = maskedFAI.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: westernBasin,
    scale: 1000,
    maxPixels: 1e9
  });

  const countEast = maskedFAI.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: easternBasin,
    scale: 1000,
    maxPixels: 1e9
  });

  const meanWest = statsWest.get('FAI').getInfo();
  const meanEast = statsEast.get('FAI').getInfo();
  const pixelsWest = countWest.get('FAI').getInfo();
  const pixelsEast = countEast.get('FAI').getInfo();

  // 5. Validation & Final Answer
  console.log(`Western FAI: ${meanWest?.toFixed(3) || 'null'}, Pixels: ${pixelsWest}`);
  console.log(`Eastern FAI: ${meanEast?.toFixed(3) || 'null'}, Pixels: ${pixelsEast}`);

  if (pixelsWest === 0 || pixelsEast === 0) {
    console.log('<answer>C2</answer>');
  } else if (meanWest === null || meanEast === null || 
             Math.abs(meanWest) > 1 || Math.abs(meanEast) > 1) {
    console.log('<answer>C3</answer>');
  } else if (meanWest > meanEast) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
